create or replace function public.film_use_call(p_user uuid) returns boolean language plpgsql security definer set search_path = public as $$ begin update film_credits set calls = calls + 1 where user_id = p_user and active_until > now() and calls < (case when active_ref like 'book%' then 40 else 20 end); return found; end $$;
create or replace function public.film_reserve_once(p_user uuid, p_ref text, p_again boolean) returns text language plpgsql security definer set search_path = public as $$ declare r film_credits%rowtype; begin insert into film_credits(user_id) values (p_user) on conflict do nothing; select * into r from film_credits where user_id = p_user for update; if r.active_ref = p_ref and r.active_until > now() and r.calls < 40 then return 'active'; end if; if r.active_ref = p_ref and not coalesce(p_again, false) then return 'expired'; end if; if r.balance <= 0 then return 'empty'; end if; update film_credits set balance = balance - 1, active_until = now() + interval '3 hours', calls = 0, active_ref = p_ref, updated_at = now() where user_id = p_user; return 'charged'; end $$;
create or replace function public.film_refund_once(p_user uuid, p_ref text) returns boolean language plpgsql security definer set search_path = public as $$ begin update film_credits set balance = balance + 1, active_until = null, active_ref = null, updated_at = now() where user_id = p_user and active_ref = p_ref and calls <= 5 and active_until > now() - interval '24 hours'; return found; end $$;
